export const WHAT_IS_TEAMWORK_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu kerja sama, tujuan bersama, saling bergantung
{n:1,type:"mcq",micro:"Apa itu kerja sama",q:"'Kerja sama' (kolaborasi) adalah...",options:["Beberapa orang bekerja bersama menuju satu tujuan yang sama, saling membantu & membagi tugas","Beberapa orang mengerjakan hal yang sama sekaligus tanpa koordinasi","Satu orang mengerjakan semua & yang lain menonton"],answer:0,explain:"Inti kerja sama: tujuan bersama + pembagian peran + saling bantu. Bukan sekadar berada di ruangan yang sama.",hint:"Tujuan bersama + saling bantu, atau sendiri-sendiri?"},
{n:2,type:"mcq",micro:"Kenapa kerja sama",q:"Manfaat utama bekerja dalam tim dibanding sendirian:",options:["Tidak ada manfaatnya","Tugas besar selesai lebih cepat, ide lebih beragam, & beban terbagi","Selalu lebih lambat & lebih ribet"],answer:1,explain:"Tim yang baik menghasilkan lebih dari jumlah anggotanya. Tim yang buruk bisa lebih lambat dari satu orang.",hint:"Lebih cepat + ide beragam + beban terbagi, atau selalu ribet?"},
{n:3,type:"mcq",micro:"Tujuan bersama",q:"Hal pertama yang perlu jelas di awal kerja kelompok:",options:["Siapa yang paling pintar","Siapa yang jadi ketua","Apa tujuan kita? Hasil akhir seperti apa yang kita mau?"],answer:2,explain:"Tanpa tujuan yang disepakati, tiap orang menuju arah berbeda & hasilnya berantakan.",hint:"Tujuan bersama dulu, atau siapa ketua dulu?"},
{n:4,type:"mcq",micro:"Saling bergantung",q:"Dalam tim, 'saling bergantung' berarti...",options:["Hasil kerja satu orang memengaruhi orang lain, jadi tiap orang perlu menepati bagiannya","Tidak ada yang butuh siapa pun","Satu orang menanggung semua"],answer:0,explain:"Kalau bagian A telat, bagian B tidak bisa mulai. Kesadaran ini membuat orang lebih bertanggung jawab.",hint:"Bagianmu memengaruhi orang lain, atau berdiri sendiri?"},
{n:5,type:"mcq",micro:"Membagi tugas",q:"Cara membagi tugas kelompok yang adil:",options:["Tidak dibagi, kerjakan bareng terus di satu bagian","Sesuaikan dengan kekuatan & minat tiap orang, seimbangkan bebannya, & pastikan semua kebagian","Semua bagian diberikan ke satu orang yang paling rajin"],answer:1,explain:"Pembagian yang baik memakai kekuatan tiap orang & tidak menumpuk beban pada satu orang.",hint:"Sesuai kekuatan + seimbang, atau tumpuk ke satu orang?"},
{n:6,type:"mcq",micro:"Menepati bagian",q:"Kalau kamu tidak menyelesaikan bagianmu tepat waktu, dampaknya bagi tim:",options:["Tidak ada dampak, itu urusanmu sendiri","Tim jadi lebih santai","Anggota lain jadi terhambat, harus buru-buru di akhir, atau menanggung bagianmu"],answer:2,explain:"Dalam tim, keterlambatanmu adalah masalah semua orang. Menepati bagian adalah bentuk menghormati tim.",hint:"Menghambat semua, atau urusanmu sendiri?"},
{n:7,type:"mcq",micro:"Saling membantu",q:"Anggota tim menyelesaikan bagiannya lebih dulu. Sikap yang baik:",options:["Menawarkan bantuan ke yang masih kesulitan: 'Punyaku udah, ada yang bisa kubantu?'","Duduk santai & menonton yang lain kewalahan","Menyombongkan diri sudah selesai"],answer:0,explain:"Tim menang atau kalah bersama. Membantu yang tertinggal mempercepat seluruh tim.",hint:"Tawarkan bantuan, atau menonton / menyombong?"},
{n:8,type:"mcq",micro:"Menghargai kontribusi",q:"Ketika anggota menyampaikan ide, respons yang mendukung kerja sama:",options:["Abaikan & lanjut bicara sendiri","Dengarkan, hargai, & pertimbangkan — meski akhirnya tidak dipakai","Langsung tolak tanpa dibahas"],answer:1,explain:"Anggota yang merasa didengar terus berkontribusi. Yang idenya selalu dibuang berhenti berbagi.",hint:"Dengar & hargai, atau tolak / abaikan?"},
{n:9,type:"order",micro:"Memulai kerja kelompok",q:"Urutkan langkah memulai kerja kelompok dengan baik.",items:["Sepakati tujuan & hasil akhir yang diinginkan","Pecah pekerjaan jadi bagian-bagian","Bagi bagian sesuai kekuatan & sepakati tenggat tiap bagian","Sepakati kapan bertemu lagi untuk mengecek kemajuan"],answer:[0,1,2,3],explain:"Tujuan → pecah pekerjaan → bagi + tenggat → jadwal cek. Ini fondasi kerja sama yang lancar.",hint:"Apa yang disepakati sebelum membagi tugas?"},
{n:10,type:"mcq",micro:"Komunikasi dalam tim",q:"Kalau kamu menghadapi kendala di bagianmu, sebaiknya...",options:["Sembunyikan sampai hari terakhir & berharap selesai sendiri","Diam & mengerjakan seadanya","Segera beri tahu tim supaya bisa dibantu atau rencana disesuaikan"],answer:2,explain:"Kendala yang disampaikan lebih awal bisa diatasi tim. Yang disembunyikan meledak di akhir.",hint:"Beri tahu lebih awal, atau sembunyikan?"},
{n:11,type:"tf",micro:"Tim menang/kalah bersama",q:"Benar atau Salah: Dalam kerja tim, keberhasilan atau kegagalan hasil akhir adalah tanggung jawab bersama, bukan hanya satu orang.",answer:true,explain:"Kalau satu bagian buruk, hasil keseluruhan terpengaruh. Tim yang sehat saling menjaga agar semua bagian jadi.",hint:"Tanggung jawab bersama, atau satu orang?"},
{n:12,type:"tf",micro:"Kerja sama = satu orang kerja",q:"Benar atau Salah: Cara paling efisien menyelesaikan tugas kelompok adalah membiarkan satu anggota yang paling pintar mengerjakan hampir semuanya.",answer:false,explain:"Sebaliknya, itu membebani satu orang, membuat yang lain tidak belajar, & rapuh kalau orang itu sakit. Membagi tugas secara adil lebih kuat & adil.",hint:"Satu orang kerja semua = efisien, atau membebani & rapuh?"},
{n:13,type:"mcq",micro:"Peran ketua",q:"Peran ketua/koordinator kelompok yang baik:",options:["Membantu tim menyepakati tujuan, mengoordinasi bagian, mengingatkan tenggat, & memastikan semua terlibat — bukan memerintah sepihak","Memutuskan segalanya sendiri & menyuruh-nyuruh","Tidak melakukan apa-apa & membiarkan kacau"],answer:0,explain:"Koordinator yang baik melayani tim: memfasilitasi, bukan mendominasi atau menghilang.",hint:"Memfasilitasi & memastikan semua terlibat, atau memerintah / hilang?"},
{n:14,type:"mcq",micro:"Menghormati waktu tim",q:"Datang tepat waktu ke pertemuan kelompok penting karena...",options:["Hanya penting kalau kamu ketuanya","Menghargai waktu anggota lain & menjaga rencana tetap berjalan","Tidak penting, yang lain bisa menunggu"],answer:1,explain:"Setiap orang yang telat membuat semua orang lain menunggu. Ketepatan waktu adalah bentuk hormat pada tim.",hint:"Menghargai waktu tim, atau 'biar mereka menunggu'?"},
{n:15,type:"mcq",micro:"Berbagi informasi",q:"Kamu menemukan sumber/data bagus untuk proyek. Sikap tim yang baik:",options:["Simpan sendiri agar bagianmu terlihat paling bagus","Bagikan hanya ke teman dekat","Bagikan ke seluruh tim supaya semua bisa memakainya"],answer:2,explain:"Menyimpan informasi berguna dari tim sendiri merugikan hasil bersama. Berbagi memperkuat semua.",hint:"Bagikan ke semua, atau simpan sendiri?"},
{n:16,type:"mcq",micro:"Perbedaan pendapat",q:"Dalam tim yang sehat, perbedaan pendapat...",options:["Wajar & bisa menghasilkan keputusan lebih baik bila dibahas dengan hormat","Berarti tim gagal","Harus selalu dihindari dengan diam"],answer:0,explain:"Tim tanpa perbedaan pendapat sering hanya mengikuti satu suara. Perbedaan yang dibahas baik = ide lebih kuat.",hint:"Wajar & bisa menguatkan, atau tanda gagal?"},
{n:17,type:"mcq",micro:"Tanggung jawab pribadi dalam tim",q:"'Aku sudah selesai bagianku, jadi kalau hasil kelompok jelek itu bukan salahku' adalah sikap...",options:["Cara terbaik menjaga diri","Kurang tepat — dalam tim, kamu juga ikut bertanggung jawab membantu bagian lain & hasil keseluruhan","Sangat dewasa"],answer:1,explain:"Kerja sama berarti peduli pada seluruh hasil, bukan hanya kotak tugasmu sendiri.",hint:"Ikut bertanggung jawab atas keseluruhan, atau 'bukan salahku'?"},
{n:18,type:"mcq",micro:"Menyemangati tim",q:"Kalimat yang menguatkan semangat tim saat lelah:",options:["'Duh, ini nggak akan kelar. Percuma.'","'Kalian lambat semua.'","'Kita udah jauh, tinggal sedikit lagi. Ayo kita selesaikan bareng.'"],answer:2,explain:"Kata-kata yang mengakui usaha & menyemangati menjaga tim tetap bergerak. Keluhan & tuduhan mematahkan.",hint:"Menyemangati, atau mengeluh / menyalahkan?"},
{n:19,type:"mcq",micro:"Kerja sama di luar tugas",q:"Contoh kerja sama dalam kehidupan sehari-hari:",options:["Membersihkan rumah bersama keluarga, piket kelas, main dalam tim olahraga, gotong royong di kampung","Hanya ada di tugas sekolah","Tidak pernah dibutuhkan di kehidupan nyata"],answer:0,explain:"Kerja sama ada di mana-mana: keluarga, kelas, tim, masyarakat. Melatihnya sekarang berguna seumur hidup.",hint:"Ada di banyak tempat, atau cuma di tugas sekolah?"},
{n:20,type:"open",micro:"Menilai kerja kelompok",q:"Kelompokmu terakhir kali: satu orang mengerjakan hampir semua, dua orang tidak ikut sama sekali, dan hasilnya nilainya kurang bagus. Jelaskan minimal 3 hal yang salah dari cara kelompok itu bekerja, dan 3 hal yang akan kamu ubah untuk kelompok berikutnya.",sample:"Yang salah: (1) Tidak ada pembagian tugas yang jelas di awal, jadi tanggung jawab tidak merata dan dua orang merasa 'tidak kebagian' atau bisa lepas tangan. (2) Beban menumpuk pada satu orang, yang berarti hasilnya bergantung pada satu sudut pandang saja dan orang itu kelelahan. (3) Tidak ada kesepakatan tenggat per bagian atau jadwal mengecek kemajuan, jadi tidak ada yang tahu siapa mengerjakan apa sampai terlambat. (4) Anggota yang tidak ikut tidak ditegur atau diajak bicara, jadi masalahnya dibiarkan. Yang akan kuubah: (1) Di pertemuan pertama, kami sepakati tujuan lalu bagi pekerjaan jadi bagian-bagian dengan nama dan tenggat masing-masing, dicatat tertulis. (2) Minta tiap orang mengonfirmasi bagiannya ('oke') supaya jelas ada kesepakatan. (3) Sepakati satu waktu cek di tengah untuk melihat kemajuan, sehingga kalau ada yang tertinggal bisa dibantu lebih awal. (4) Kalau ada yang tidak mengerjakan bagiannya, aku bicara langsung dengan sopan menanyakan kendalanya sebelum masalahnya membesar, dan bila perlu melibatkan guru berdasarkan fakta pembagian kerja.",explain:"Jawaban baik menyebut minimal 3 kesalahan (tidak ada pembagian jelas, beban menumpuk, tidak ada tenggat/cek kemajuan, anggota pasif dibiarkan) dan 3 perubahan konkret (pembagian tertulis + tenggat, konfirmasi tiap anggota, jadwal cek di tengah, menangani anggota pasif lebih awal).",hint:"Pikirkan: pembagian tugas, keseimbangan beban, tenggat & cek kemajuan, cara menangani anggota yang tidak ikut."},

// FASE B — PEMAHAMAN (21-40): ciri tim sehat, free-rider, peran, kepercayaan
{n:21,type:"classify",micro:"Perilaku tim: membantu vs merusak",q:"Kelompokkan tiap perilaku ke 'Menguatkan tim' atau 'Merusak tim'.",items:["Menepati bagian tepat waktu & mengabari bila ada kendala","Menyimpan informasi berguna agar terlihat paling menonjol","Menawarkan bantuan ke anggota yang kesulitan","Menyalahkan orang lain saat ada masalah tanpa mencari solusi"],groups:["Menguatkan tim","Merusak tim"],answer:{"Menguatkan tim":["Menepati bagian tepat waktu & mengabari bila ada kendala","Menawarkan bantuan ke anggota yang kesulitan"],"Merusak tim":["Menyimpan informasi berguna agar terlihat paling menonjol","Menyalahkan orang lain saat ada masalah tanpa mencari solusi"]},explain:"Menguatkan: keandalan, komunikasi, saling bantu. Merusak: menyembunyikan, menyalahkan, bersaing di dalam tim.",hint:"Membuat tim lebih kuat, atau melemahkan?"},
{n:22,type:"mcq",micro:"Ciri tim yang sehat",q:"Ciri tim yang bekerja dengan baik:",options:["Setiap orang bersaing untuk terlihat paling hebat","Tujuan jelas, peran jelas, komunikasi terbuka, saling percaya & bantu, konflik dibahas dengan hormat","Semua diam & mengikuti satu orang tanpa bertanya"],answer:1,explain:"Tim hebat bukan tim tanpa masalah — melainkan tim yang bisa membicarakan masalahnya dengan aman.",hint:"Tujuan & peran jelas + komunikasi terbuka, atau diam / bersaing?"},
{n:23,type:"mcq",micro:"'Penumpang gelap' (free-rider)",q:"'Penumpang gelap' dalam kelompok adalah...",options:["Anggota yang mengerjakan bagian terberat","Ketua kelompok","Anggota yang ikut menikmati hasil & nilai kelompok tapi tidak berkontribusi"],answer:2,explain:"Penumpang gelap merugikan yang lain & merusak semangat. Perlu ditangani dengan bicara langsung, bukan dipendam.",hint:"Ikut menikmati tanpa berkontribusi, atau kerja terberat?"},
{n:24,type:"mcq",micro:"Menangani penumpang gelap",q:"Anggota kelompok terus tidak mengerjakan bagiannya. Langkah pertama yang tepat:",options:["Bicara langsung & berdua dengan sopan: 'Bagianmu belum jalan, ada kendala? Kita butuh itu buat lanjut.'","Langsung melapor ke guru tanpa bicara ke orangnya","Mengerjakan bagiannya diam-diam sambil kesal"],answer:0,explain:"Beri kesempatan & pahami kendalanya dulu. Eskalasi ke guru bila sudah bicara & tetap tidak ada perubahan.",hint:"Bicara langsung dulu, atau lapor / kerjakan sendiri?"},
{n:25,type:"mcq",micro:"Kepercayaan dalam tim",q:"Kepercayaan antar anggota tim dibangun dari...",options:["Tidak bisa dibangun, hanya keberuntungan","Pengalaman berulang: orang menepati janji, jujur soal kendala, & membantu saat dibutuhkan","Satu janji besar di awal"],answer:1,explain:"Kepercayaan tumbuh dari konsistensi kecil. Sekali ingkar janji besar bisa merusaknya.",hint:"Konsistensi kecil berulang, atau satu janji besar?"},
{n:26,type:"mcq",micro:"Peran dalam tim",q:"Selain 'yang mengerjakan tugas', tim sering butuh peran seperti...",options:["Hanya satu peran: pekerja","Peran tidak penting","Koordinator (mengatur), pencatat (merangkum), pengecek kualitas, penjaga waktu, penyemangat"],answer:2,explain:"Tim yang efektif mengenali & membagi peran-peran ini, kadang satu orang memegang beberapa.",hint:"Beberapa peran berbeda, atau semua sama?"},
{n:27,type:"tf",micro:"Konflik tim selalu buruk?",q:"Benar atau Salah: Perbedaan pendapat & konflik ide dalam tim selalu menandakan tim yang tidak sehat & harus dihindari.",answer:false,explain:"Sebaliknya, konflik ide yang dibahas dengan hormat sering menghasilkan keputusan lebih baik. Yang berbahaya adalah konflik pribadi yang dibiarkan atau tim yang takut berbeda pendapat.",hint:"Konflik ide = selalu buruk, atau bisa menguatkan bila dibahas baik?"},
{n:28,type:"tf",micro:"Komunikasi rutin",q:"Benar atau Salah: Menetapkan waktu rutin untuk mengecek kemajuan (mis. pesan singkat setiap 2 hari atau pertemuan pendek) membantu tim menemukan & mengatasi masalah lebih awal.",answer:true,explain:"Tanpa cek rutin, masalah baru ketahuan di akhir saat sudah sulit diperbaiki. Cek pendek & teratur murah & efektif.",hint:"Cek rutin membantu, atau buang waktu?"},
{n:29,type:"mcq",micro:"Menghargai gaya kerja berbeda",q:"Anggota timmu suka mengerjakan tugas jauh sebelum tenggat; kamu suka mendekati tenggat. Sikap tim yang baik:",options:["Hormati perbedaan, tapi sepakati tenggat internal bersama yang bisa dipenuhi semua","Paksa semua bekerja dengan gayamu","Tidak menyepakati apa pun & berharap semua beres"],answer:0,explain:"Perbedaan gaya wajar. Yang penting: kesepakatan bersama soal kapan bagian harus jadi.",hint:"Hormati + sepakati tenggat bersama, atau paksa satu gaya?"},
{n:30,type:"order",micro:"Membangun kesepakatan tim di awal",q:"Urutkan langkah membuat 'kesepakatan tim' di pertemuan pertama.",items:["Sepakati tujuan & apa arti 'berhasil' bagi kelompok ini","Sepakati cara komunikasi (grup chat mana, seberapa sering cek)","Sepakati pembagian tugas, tenggat internal, & standar kualitas","Sepakati cara menyelesaikan ketidaksepakatan bila muncul"],answer:[0,1,2,3],explain:"Tujuan → komunikasi → tugas & standar → cara selesaikan konflik. Kesepakatan awal mencegah banyak masalah.",hint:"Apa yang disepakati paling dasar dulu?"},
{n:31,type:"mcq",micro:"Beban tidak merata",q:"Kamu merasa bagianmu jauh lebih berat dari yang lain. Sikap tim yang sehat:",options:["Berhenti mengerjakan tanpa bilang","Sampaikan dengan tenang & data: 'Bagianku kayaknya lebih besar, bisa kita bagi ulang sebagian?'","Kerjakan semua sambil diam-diam kesal & mengeluh ke orang luar"],answer:1,explain:"Ketidakadilan yang disuarakan bisa diperbaiki. Yang dipendam menumpuk jadi kekesalan & merusak tim.",hint:"Sampaikan tenang + usul bagi ulang, atau pendam / berhenti diam-diam?"},
{n:32,type:"tf",micro:"Semua ide harus dari ketua?",q:"Benar atau Salah: Dalam tim yang baik, hanya ketua yang boleh mengusulkan ide; anggota lain sebaiknya mengikuti saja.",answer:false,explain:"Sebaliknya, tim terkuat memanfaatkan ide dari semua anggota. Ketua yang baik justru mengajak semua berkontribusi.",hint:"Hanya ide ketua, atau ide semua anggota?"},
{n:33,type:"mcq",micro:"Mengakui kontribusi",q:"Saat presentasi hasil kelompok, cara yang adil:",options:["Aku klaim semua ide sebagai milikku","Tidak menyebut siapa pun","Sebut kontribusi tiap anggota & sampaikan sebagai hasil bersama"],answer:2,explain:"Mengakui kontribusi orang membuat mereka merasa dihargai & mau bekerja sama lagi di masa depan.",hint:"Akui kontribusi tiap orang, atau klaim sendiri?"},
{n:34,type:"mcq",micro:"Tim & tanggung jawab bersama",q:"Kalau satu anggota gagal & hasil kelompok buruk, sikap tim yang matang:",options:["Refleksi bersama: apa yang bisa kita lakukan berbeda sebagai tim, termasuk cara kita mendukung anggota yang kesulitan?","Menyalahkan satu orang & selesai","Menyembunyikan siapa yang gagal"],answer:0,explain:"Kegagalan tim jarang murni salah satu orang; sering ada kegagalan tim dalam mendukung & mengecek.",hint:"Refleksi bersama, atau menyalahkan satu orang?"},
{n:35,type:"mcq",micro:"Batas menolong anggota",q:"Membantu anggota yang kesulitan itu baik, tapi mengerjakan seluruh bagiannya untuknya...",options:["Membuat tim lebih kuat selamanya","Bisa merugikan: ia tidak belajar, kamu kelelahan, & kalau berulang jadi tidak adil","Selalu solusi terbaik"],answer:1,explain:"Bantu ia mengerjakan (menjelaskan, mendampingi), bukan menggantikan sepenuhnya. Kecuali situasi darurat sesekali.",hint:"Bantu mengerjakan, atau kerjakan seluruhnya untuknya?"},
{n:36,type:"mcq",micro:"Rasa aman dalam tim",q:"Tim di mana anggota nyaman berkata 'aku belum paham' atau 'aku salah' cenderung...",options:["Lebih lambat karena banyak yang mengaku bingung","Selalu gagal","Menemukan & memperbaiki masalah lebih cepat karena tidak ada yang menyembunyikan kesulitan"],answer:2,explain:"Rasa aman untuk jujur = masalah kecil ketahuan sebelum jadi besar. Tim yang menghukum kejujuran menyembunyikan masalah.",hint:"Masalah cepat ketahuan, atau lebih lambat?"},
{n:37,type:"tf",micro:"Kerja sama butuh dilatih",q:"Benar atau Salah: Kemampuan bekerja sama dengan baik dalam tim adalah sifat bawaan; orang yang tidak memilikinya sejak awal tidak bisa belajar.",answer:false,explain:"Sebaliknya, membagi tugas, menyelesaikan konflik, berkomunikasi, & menepati bagian semuanya keterampilan yang bisa dilatih dengan kesadaran & latihan.",hint:"Otomatis/bawaan, atau keterampilan yang dilatih?"},
{n:38,type:"mcq",micro:"Menyambut anggota baru/pendiam",q:"Ada anggota yang pendiam & jarang bicara di kelompok. Sikap tim yang inklusif:",options:["Sengaja mengundang pendapatnya: 'Menurutmu gimana, [nama]?' tanpa memaksa, & memberi peran yang cocok","Membiarkannya diam & tidak melibatkan","Menyuruhnya 'jangan pendiam dong'"],answer:0,explain:"Anggota pendiam sering punya ide bagus tapi butuh ruang & undangan. Membiarkan mereka diam = kehilangan kontribusi.",hint:"Undang dengan lembut, atau biarkan / paksa?"},
{n:39,type:"mcq",micro:"Menjaga fokus tim",q:"Saat rapat kelompok melebar ke obrolan tidak penting terlalu lama:",options:["Marah pada yang mengobrol","Seseorang bisa mengarahkan kembali dengan sopan: 'Seru sih, tapi balik ke tugas yuk, waktunya mepet.'","Biarkan saja & rapat jadi tidak selesai"],answer:1,explain:"Menjaga tim tetap pada tujuan adalah tanggung jawab bersama, bisa dilakukan siapa saja dengan sopan.",hint:"Arahkan kembali dengan sopan, atau biarkan / marah?"},
{n:40,type:"open",micro:"Merancang kesepakatan tim",q:"Kamu dan 3 teman akan mengerjakan proyek besar selama 2 minggu. Tulis 'kesepakatan tim' berisi minimal 5 poin yang akan kalian sepakati di pertemuan pertama, dengan alasan tiap poin.",sample:"Kesepakatan tim: (1) Tujuan kami: menghasilkan [hasil akhir] yang [standar, mis. lengkap, rapi, tepat waktu]. Alasan: supaya semua menuju arah yang sama. (2) Komunikasi lewat grup chat khusus proyek; wajib mengecek minimal sekali sehari; balas dalam waktu wajar. Alasan: supaya info tidak tercecer dan masalah cepat ketahuan. (3) Pembagian tugas: tiap orang pegang satu bagian utama sesuai kekuatannya, dicatat tertulis dengan tenggat internal 2 hari sebelum tenggat asli. Alasan: beban merata dan ada waktu untuk menggabungkan dan memperbaiki. (4) Pertemuan cek kemajuan setiap 3 hari (bisa online, 20 menit): tiap orang melapor sudah sampai mana dan ada kendala apa. Alasan: menemukan masalah lebih awal. (5) Kalau ada yang tidak bisa menyelesaikan bagiannya, wajib mengabari minimal 1 hari sebelumnya supaya tim bisa membantu atau menyesuaikan; tidak boleh menghilang mendadak. Alasan: melindungi hasil bersama. (6) Kalau ada perbedaan pendapat, kami bahas terbuka, dengar semua alasan, lalu putuskan bersama (voting atau kompromi); setelah diputuskan, semua mendukung. Alasan: supaya konflik tidak berlarut. (7) Saat presentasi, kontribusi tiap orang disebut dan hasil disampaikan sebagai kerja bersama. Alasan: adil dan menjaga semangat.",explain:"Jawaban baik memuat minimal 5 poin dengan alasan, mencakup: tujuan/standar bersama, cara & frekuensi komunikasi, pembagian tugas tertulis + tenggat internal, jadwal cek kemajuan, aturan bila ada yang tidak bisa menyelesaikan bagiannya, cara menyelesaikan perbedaan pendapat, pengakuan kontribusi.",hint:"Turunkan tiap fondasi kerja sama jadi satu aturan konkret: tujuan, komunikasi, pembagian+tenggat, cek kemajuan, aturan kendala, cara putuskan konflik."},

// FASE C — PENERAPAN (41-60): skenario
{n:41,type:"mcq",micro:"Skenario: anggota dominan",q:"Satu anggota selalu mendominasi & memutuskan sendiri, anggota lain jadi pasif. Langkah yang membangun:",options:["Diam & membiarkan dominasi","Menyerang si dominan di depan semua","'Aku pengin dengar pendapat yang lain juga sebelum kita putuskan. [nama], [nama], gimana menurut kalian?'"],answer:2,explain:"Membuka ruang untuk suara lain lebih efektif & tidak memicu pertahanan dibanding menyerang si dominan.",hint:"Buka ruang untuk yang lain, atau diam / menyerang?"},
{n:42,type:"mcq",micro:"Skenario: kendala mendadak",q:"Kamu tiba-tiba sakit & tidak bisa menyelesaikan bagianmu tepat waktu. Sikap tim yang baik:",options:["Segera kabari tim, jelaskan situasinya, & bantu cari solusi (mis. serahkan yang sudah dikerjakan, minta bantuan)","Diam saja & berharap ada yang menyadari","Menghilang tanpa kabar"],answer:0,explain:"Kendala di luar kendalimu tetap perlu dikomunikasikan agar tim bisa menyesuaikan rencana.",hint:"Kabari + bantu cari solusi, atau diam / menghilang?"},
{n:43,type:"mcq",micro:"Skenario: dua bagian bertabrakan",q:"Bagianmu & bagian temanmu ternyata tumpang tindih & saling bertentangan. Langkah:",options:["Menyalahkan siapa yang salah paham","Bicara berdua, samakan pemahaman soal tujuan, & putuskan siapa mengerjakan apa; libatkan tim bila perlu","Masing-masing tetap mengerjakan versinya & biarkan bentrok di akhir"],answer:1,explain:"Tumpang tindih adalah tanda pembagian tugas kurang jelas. Selesaikan dengan komunikasi, bukan saling menyalahkan.",hint:"Bicara + perjelas pembagian, atau jalan sendiri-sendiri / menyalahkan?"},
{n:44,type:"mcq",micro:"Skenario: standar kualitas berbeda",q:"Kamu ingin hasil rapi & lengkap; anggota lain merasa 'yang penting selesai'. Sikap:",options:["Diam-diam memperbaiki semua kerjaan mereka sambil kesal","Menyerah & membiarkan hasil seadanya","Bahas bersama: sepakati standar minimum yang semua setuju & bisa dicapai dalam waktu yang ada"],answer:2,explain:"Standar yang tidak dibicarakan menjadi sumber kekecewaan. Sepakati bersama di awal atau saat masalah muncul.",hint:"Sepakati standar bersama, atau perbaiki diam-diam / menyerah?"},
{n:45,type:"order",micro:"Menyatukan bagian jadi satu hasil",q:"Urutkan langkah menggabungkan bagian-bagian anggota jadi satu hasil yang utuh.",items:["Sepakati format & gaya yang seragam sebelum masing-masing mulai","Kumpulkan semua bagian beberapa hari sebelum tenggat","Gabungkan & sesuaikan agar nyambung (transisi, format, gaya)","Cek bersama sebagai tim & perbaiki bagian yang kurang"],answer:[0,1,2,3],explain:"Sepakati format di awal → kumpulkan lebih awal → gabungkan & selaraskan → cek bersama. Jangan menggabung di menit terakhir.",hint:"Apa yang disepakati sebelum masing-masing mengerjakan bagiannya?"},
{n:46,type:"mcq",micro:"Skenario: konflik pribadi antar anggota",q:"Dua anggota tim sedang tidak akur karena masalah pribadi & itu mengganggu kerja. Sikap:",options:["Ingatkan dengan tenang bahwa kalian punya tujuan bersama; bila perlu, minta mereka menyelesaikan masalah pribadinya di luar kerja tim atau libatkan guru/penengah","Ikut memihak salah satu","Membiarkan sampai proyek berantakan"],answer:0,explain:"Konflik pribadi yang dibawa ke tim perlu diakui & dipisahkan dari tugas, kadang dengan bantuan penengah.",hint:"Fokus ke tujuan bersama + pisahkan masalah pribadi, atau memihak / membiarkan?"},
{n:47,type:"mcq",micro:"Skenario: kamu tidak setuju keputusan tim",q:"Tim memutuskan sesuatu yang kamu tidak setujui, tapi mayoritas memilih itu. Sikap dewasa:",options:["Terus mengungkit-ungkit ketidaksetujuanmu sepanjang proyek","Sampaikan keberatanmu sekali dengan jelas; kalau tetap kalah suara, dukung keputusan tim & beri yang terbaik","Menyabotase diam-diam karena kesal"],answer:1,explain:"Dalam tim, kadang idemu tidak menang. Menyuarakan sekali lalu mendukung keputusan bersama adalah tanda kematangan.",hint:"Suarakan sekali lalu dukung, atau sabotase / ungkit terus?"},
{n:48,type:"mcq",micro:"Skenario: anggota berbakat tapi sulit diajak koordinasi",q:"Seorang anggota sangat jago tapi suka mengerjakan sendiri tanpa mengabari & tidak ikut rapat. Sikap:",options:["Biarkan karena hasilnya bagus","Keluarkan dia dari kelompok","Bicara berdua: hargai kemampuannya, tapi jelaskan tim butuh update & keselarasan supaya bagiannya nyambung dengan yang lain"],answer:2,explain:"Kemampuan individu tinggi tidak menggantikan koordinasi. Sampaikan kebutuhan tim dengan tetap menghargai.",hint:"Hargai + jelaskan kebutuhan koordinasi, atau biarkan / keluarkan?"},
{n:49,type:"mcq",micro:"Skenario: tim kehabisan waktu",q:"Tenggat besok & masih banyak yang belum selesai. Sikap tim yang produktif:",options:["Kumpul (atau chat), lihat apa yang wajib ada vs bisa dikorbankan, bagi ulang sisa pekerjaan, kerjakan bareng bagian kritis","Saling menyalahkan siapa yang bikin telat","Menyerah & tidak mengumpulkan"],answer:0,explain:"Krisis waktu butuh koordinasi cepat: prioritas, bagi ulang, kerja bareng. Menyalahkan hanya membuang sisa waktu.",hint:"Prioritas + bagi ulang + kerja bareng, atau saling menyalahkan?"},
{n:50,type:"open",micro:"Skenario menyeluruh: menyelamatkan tim",q:"Seminggu menjelang tenggat, kelompokmu berantakan: dua anggota belum mulai bagiannya, satu anggota (kamu) sudah selesai, dan komunikasi macet. Rancang langkah-langkah yang akan kamu ambil sebagai anggota (bukan ketua) untuk membantu menyelamatkan proyek.",sample:"(1) Aku mulai dari membuka komunikasi: kirim pesan ke grup yang tenang dan tidak menyalahkan — 'Teman-teman, tenggat tinggal seminggu dan sepertinya kita agak tertinggal. Yuk kita ketemu/chat besok jam X buat lihat kondisi dan atur ulang.' (2) Di pertemuan itu, minta tiap orang jujur sudah sampai mana dan apa kendalanya — mungkin ada yang bingung mulai dari mana, bukan malas. (3) Bantu memecah bagian yang belum jalan menjadi potongan lebih kecil dan konkret, sehingga terasa lebih mungkin dikerjakan dalam seminggu. (4) Tawarkan bantuanku: karena bagianku sudah selesai, aku bisa mengambil satu potongan tambahan atau membantu salah satu yang tertinggal (mendampingi, bukan mengerjakan penuh). (5) Usulkan tenggat internal harian yang jelas untuk sisa minggu dan cek singkat tiap hari lewat chat. (6) Kalau setelah semua upaya ini masih ada anggota yang benar-benar tidak merespons atau tidak mengerjakan, aku sampaikan ke kelompok bahwa kita perlu memberi tahu guru kondisinya secara jujur dan berdasarkan fakta, supaya penilaian adil dan proyek tetap bisa diselesaikan oleh yang mau bekerja. (7) Selama proses, aku menjaga nada tetap fokus pada solusi dan menyemangati, bukan menyalahkan, supaya orang mau kembali terlibat.",explain:"Jawaban baik: membuka komunikasi dengan nada solusi (bukan menyalahkan), mengadakan cek kondisi jujur, memecah pekerjaan besar jadi potongan konkret, menawarkan bantuan nyata (mendampingi, bukan menggantikan penuh), menetapkan tenggat internal + cek harian, dan eskalasi ke guru berbasis fakta hanya bila upaya tim gagal — sambil menjaga nada menyemangati.",hint:"Buka komunikasi tanpa menyalahkan, cek kondisi jujur, pecah pekerjaan, tawarkan bantuan, tenggat harian + cek, eskalasi fakta sebagai jalan terakhir."},
{n:51,type:"mcq",micro:"Skenario: memberi peran ke tiap anggota",q:"Tim 4 orang mengerjakan poster. Cara membagi peran yang memakai kekuatan tiap orang:",options:["Undi secara acak tanpa melihat kemampuan","Yang jago menggambar → desain; yang teliti → cek fakta & data; yang rapi menulis → teks; yang suka mengatur → koordinasi & gabungkan","Semua mengerjakan semua bagian bersama-sama sepanjang waktu"],answer:1,explain:"Mencocokkan peran dengan kekuatan membuat kerja lebih cepat & hasil lebih baik, sambil tiap orang tetap belajar.",hint:"Cocokkan peran dengan kekuatan, atau semua kerjakan semua / undi acak?"},
{n:52,type:"tf",micro:"Update singkat lebih baik daripada diam",q:"Benar atau Salah: Sebaiknya kamu tidak mengganggu tim dengan update apa pun sampai bagianmu benar-benar 100% selesai.",answer:false,explain:"Sebaliknya, update singkat ('bagianku 70%, sisa referensi') memberi tim gambaran kemajuan & kesempatan membantu bila kamu tertinggal. Diam membuat tim menebak-nebak.",hint:"Update singkat, atau diam sampai beres?"},
{n:53,type:"mcq",micro:"Skenario: anggota minta kelompok pindah",q:"Seorang anggota merasa tidak cocok & ingin pindah kelompok. Sikap yang matang dari tim:",options:["Menghina & menyebarkan bahwa dia pengkhianat","Memaksanya tetap sambil memusuhinya","Coba pahami alasannya & selesaikan bila bisa; kalau memang lebih baik untuk semua, bantu proses pindah dengan baik tanpa drama"],answer:2,explain:"Kadang komposisi tim memang kurang pas. Menangani perpindahan dengan dewasa lebih baik daripada memaksa & memusuhi.",hint:"Pahami + tangani dengan baik, atau hina / paksa?"},
{n:54,type:"mcq",micro:"Skenario: kamu yang jadi 'penumpang gelap'",q:"Kamu sadar minggu ini kamu kurang berkontribusi ke tim karena sibuk. Sikap bertanggung jawab:",options:["Akui ke tim, minta maaf, & tawarkan mengambil bagian ekstra atau mengejar ketertinggalan","Berharap tidak ada yang menyadari","Membela diri bahwa yang lain juga santai"],answer:0,explain:"Mengakui & memperbaiki kontribusi yang kurang jauh lebih dihargai tim daripada menyembunyikan atau membela diri.",hint:"Akui + tawarkan mengejar, atau sembunyi / membela diri?"},
{n:55,type:"mcq",micro:"Skenario: keputusan cepat dibutuhkan",q:"Tim harus memutuskan sesuatu segera tapi anggota tersebar & tidak semua bisa dihubungi. Cara yang wajar:",options:["Putuskan sendiri & tidak memberi tahu siapa pun","Kumpulkan pendapat yang bisa dihubungi, ambil keputusan sementara yang masuk akal, & kabari semua secepatnya untuk masukan/revisi","Tunggu sampai semua bisa berkumpul meski tenggat lewat"],answer:1,explain:"Keputusan sementara + transparansi lebih baik daripada macet total atau keputusan diam-diam.",hint:"Keputusan sementara + kabari semua, atau macet / diam-diam?"},
{n:56,type:"mcq",micro:"Skenario: menghargai anggota yang jarang disorot",q:"Anggota yang mengerjakan tugas 'di belakang layar' (mencari data, merapikan format) sering tidak terlihat. Sikap:",options:["Anggap kontribusinya kecil","Berikan semua pujian ke yang presentasi","Sebut & hargai kontribusinya secara terbuka; pekerjaan pendukung sama pentingnya dengan yang tampil"],answer:2,explain:"Tim yang menghargai semua jenis kontribusi membuat semua anggota mau memberikan yang terbaik.",hint:"Hargai kontribusi 'di belakang layar', atau anggap kecil?"},
{n:57,type:"tf",micro:"Kesepakatan tim lebih baik tertulis",q:"Benar atau Salah: Menuliskan pembagian tugas & tenggat (bukan hanya menyepakatinya secara lisan) mengurangi 'kukira kamu yang kerjakan' di kemudian hari.",answer:true,explain:"Catatan tertulis menjadi acuan bersama. Ingatan lisan mudah berbeda antar orang.",hint:"Tertulis lebih jelas, atau lisan cukup?"},
{n:58,type:"mcq",micro:"Skenario: memberi umpan balik ke anggota",q:"Bagian seorang anggota kurang bagus & perlu diperbaiki. Cara menyampaikan yang menjaga tim:",options:["Berdua & sopan: sebut yang sudah bagus, lalu bagian spesifik yang perlu diperbaiki + saran, tawarkan bantuan","Kritik keras di depan seluruh tim","Perbaiki diam-diam & tidak bilang apa-apa"],answer:0,explain:"Umpan balik yang membangun (privat, spesifik, dengan saran) menjaga anggota tetap termotivasi & tim tetap solid.",hint:"Berdua + spesifik + saran, atau kritik terbuka / diam-diam?"},
{n:59,type:"mcq",micro:"Skenario: merayakan keberhasilan tim",q:"Setelah proyek selesai dengan baik, sikap tim yang sehat:",options:["Langsung bubar tanpa apresiasi","Akui usaha semua orang, rayakan bersama, & catat apa yang berjalan baik untuk proyek berikutnya","Ketua mengambil semua pujian"],answer:1,explain:"Merayakan bersama & merefleksikan keberhasilan menguatkan ikatan tim & pelajaran untuk lain kali.",hint:"Akui semua + rayakan bersama, atau ketua ambil pujian / bubar?"},
{n:60,type:"open",micro:"Menangani anggota yang tidak berkontribusi",q:"Dalam kelompokmu, satu anggota (Deni) sudah dua kali tidak mengerjakan bagiannya dan tidak merespons chat, padahal tenggat dekat. Rancang langkah-langkah yang akan kamu ambil sebagai tim, secara berjenjang.",sample:"Langkah berjenjang: (1) Coba hubungi Deni secara pribadi (bukan hanya di grup) dengan nada tidak menyerang: 'Hei Deni, aku belum lihat update bagianmu dan chat grup belum kamu bales. Semuanya oke? Ada kendala yang bisa dibantu?' Mungkin ada masalah pribadi atau dia bingung mulai dari mana. (2) Kalau dia merespons dan ada kendala nyata, bantu pecah bagiannya jadi lebih kecil, dampingi memulai, dan sepakati tenggat baru yang realistis dengan cek harian. (3) Kalau dia merespons tapi tidak juga bekerja, tim menyampaikan dengan jelas dampaknya: 'Deni, kalau bagian ini nggak jadi, hasil kelompok kita ikut kena. Kami butuh kamu kerjakan minimal bagian X sebelum hari Y. Kalau nggak bisa, tolong kabari sekarang biar kami atur ulang.' (4) Sambil menunggu, tim menyiapkan rencana cadangan: bagi bagian Deni ke anggota lain yang sanggup, supaya proyek tidak sepenuhnya bergantung padanya. (5) Kalau setelah semua ini Deni tetap tidak berkontribusi dan tidak merespons, tim menemui guru bersama-sama, menjelaskan kronologi dan pembagian kerja yang sebenarnya secara jujur dan berdasarkan bukti (chat, catatan pembagian tugas), dan meminta agar penilaian mempertimbangkan kontribusi masing-masing. (6) Kami tidak menyebarkan keburukan Deni ke teman-teman lain atau mempermalukannya di grup; urusan diselesaikan lewat jalur yang tepat.",explain:"Jawaban baik menunjukkan langkah berjenjang: hubungi pribadi dengan nada memahami → bantu bila ada kendala nyata → sampaikan dampak & tenggat tegas bila tetap pasif → siapkan rencana cadangan → eskalasi ke guru bersama berdasarkan bukti sebagai jalan terakhir → tanpa mempermalukan di depan umum.",hint:"Mulai dari memahami (hubungi pribadi), lalu bantu, lalu tegas soal dampak, siapkan cadangan, eskalasi berbasis bukti sebagai akhir, tanpa gosip."},

// FASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Mengapa tujuan bersama penting",q:"Mengapa menyepakati tujuan bersama di awal sangat menentukan hasil kerja tim?",options:["Karena tujuan membuat kerja lebih lama","Tujuan tidak berpengaruh pada hasil","Tanpa tujuan yang sama, tiap anggota membuat keputusan berdasarkan bayangan berbeda, & hasilnya tidak nyambung"],answer:2,explain:"Tujuan bersama adalah 'kompas' yang membuat ratusan keputusan kecil tiap anggota mengarah ke tempat yang sama.",hint:"Keputusan tiap anggota jadi searah, atau tak berpengaruh?"},
{n:62,type:"mcq",micro:"Mengapa penumpang gelap merusak",q:"Mengapa satu penumpang gelap bisa merusak semangat seluruh tim, bukan hanya menambah beban?",options:["Anggota lain merasa tidak adil & mulai berpikir 'kenapa aku harus kerja keras kalau dia dapat nilai sama tanpa usaha?'","Karena penumpang gelap selalu berisik","Tidak merusak semangat, hanya menambah kerja"],answer:0,explain:"Ketidakadilan yang dibiarkan menular: orang lain ikut mengurangi usaha. Karena itu perlu ditangani, bukan didiamkan.",hint:"Menular jadi ketidakadilan & menurunkan usaha semua, atau sekadar tambah beban?"},
{n:63,type:"tf",micro:"Tim > jumlah anggota",q:"Benar atau Salah: Tim yang bekerja sama dengan baik bisa menghasilkan sesuatu yang lebih besar & lebih baik daripada jumlah kerja tiap anggota bila mereka bekerja sendiri-sendiri.",answer:true,explain:"Ide saling melengkapi, kelemahan satu ditutupi kekuatan lain, & umpan balik memperbaiki hasil. Ini disebut sinergi.",hint:"Tim bisa melebihi jumlah anggotanya, atau selalu sama saja?"},
{n:64,type:"mcq",micro:"Menilai kesehatan tim",q:"Tanda tim sedang tidak sehat:",options:["Ada pembagian tugas & cek kemajuan rutin","Orang menyembunyikan kesulitan, konflik dipendam, keputusan didominasi satu orang, & tidak ada yang tahu kemajuan yang lain","Anggota bertanya saat bingung & konflik ide dibahas terbuka"],answer:1,explain:"Tim tidak sehat sering terlihat tenang di permukaan (tidak ada 'ribut') tapi masalah menumpuk di bawah.",hint:"Menyembunyikan & mendominasi, atau bertanya & membahas terbuka?"},
{n:65,type:"mcq",micro:"Mengapa komunikasi rutin mengalahkan komunikasi banyak",q:"Cek singkat teratur (5 menit tiap 2 hari) sering lebih efektif daripada satu rapat panjang seminggu sekali karena...",options:["Rapat panjang selalu lebih baik","Tidak ada bedanya","Masalah ketahuan & diperbaiki lebih cepat, sebelum menumpuk selama seminggu"],answer:2,explain:"Frekuensi lebih penting daripada durasi untuk menangkap masalah sejak kecil.",hint:"Menangkap masalah lebih dini, atau tak ada beda?"},
{n:66,type:"tf",micro:"Semua anggota harus setuju bulat?",q:"Benar atau Salah: Setiap keputusan tim harus disetujui bulat oleh semua anggota, kalau tidak keputusan itu tidak sah.",answer:false,explain:"Sebaliknya, memaksakan kesepakatan bulat sering membuat tim macet. Sering cukup: dengar semua pendapat, putuskan bersama (kompromi/voting), lalu semua mendukung hasilnya.",hint:"Wajib bulat, atau dengar semua lalu putuskan bersama?"},
{n:67,type:"mcq",micro:"Peran & fleksibilitas",q:"Membagi peran itu penting, tapi tim yang baik juga...",options:["Fleksibel: anggota membantu di luar perannya saat dibutuhkan, tidak berkata 'itu bukan bagianku'","Kaku: tiap orang hanya menyentuh bagiannya sendiri apa pun yang terjadi","Tidak pernah membagi peran"],answer:0,explain:"Peran memberi kejelasan; fleksibilitas memberi ketahanan saat ada yang tumbang atau bagian tertentu lebih berat.",hint:"Fleksibel saling bantu, atau kaku 'bukan bagianku'?"},
{n:68,type:"mcq",micro:"Kepercayaan & kecepatan",q:"Mengapa tim yang anggotanya saling percaya biasanya bekerja lebih cepat?",options:["Kepercayaan tidak memengaruhi kecepatan","Mereka tidak perlu mengecek & mengawasi satu sama lain terus-menerus, & berani mendelegasikan","Karena mereka tidak pernah salah"],answer:1,explain:"Ketidakpercayaan menambah 'biaya' berupa pengawasan, pengulangan, & keraguan. Kepercayaan menghilangkan gesekan itu.",hint:"Kurang pengawasan & berani delegasi, atau tak berpengaruh?"},
{n:69,type:"mcq",micro:"Menilai kontribusi yang tidak terlihat",q:"Anggota yang paling banyak bicara di rapat belum tentu yang paling banyak berkontribusi, karena...",options:["Yang banyak bicara selalu berkontribusi paling banyak","Kontribusi hanya diukur dari bicara di rapat","Sebagian kontribusi penting terjadi di luar rapat: riset, menulis, merapikan, menghubungkan orang, menjaga semangat"],answer:2,explain:"Menilai kontribusi tim secara adil butuh melihat semua jenis pekerjaan, tidak hanya yang terlihat & terdengar.",hint:"Kontribusi ada banyak jenis, atau hanya bicara di rapat?"},
{n:70,type:"order",micro:"Menyelesaikan ketidaksepakatan tim",q:"Urutkan cara tim menyelesaikan ketidaksepakatan tentang arah proyek.",items:["Tiap pihak menjelaskan usulannya & alasannya tanpa dipotong","Cari titik temu: apa yang sebenarnya sama-sama diinginkan?","Timbang pilihan berdasarkan tujuan & batasan (waktu, kemampuan)","Putuskan bersama (kompromi/voting), catat keputusannya, & semua mendukung"],answer:[0,1,2,3],explain:"Dengar semua → cari titik temu → timbang dengan tujuan → putuskan & dukung. Bukan yang paling keras yang menang.",hint:"Apa yang dilakukan sebelum menimbang pilihan?"},
{n:71,type:"mcq",micro:"Kerja sama & belajar",q:"Selain menyelesaikan tugas, kerja tim yang baik juga...",options:["Membuat anggota belajar dari kekuatan & cara kerja satu sama lain","Membuat anggota tidak belajar apa-apa","Hanya soal nilai"],answer:0,explain:"Dalam tim yang sehat, kamu menyerap keterampilan & sudut pandang anggota lain — nilai jangka panjang di luar tugas itu sendiri.",hint:"Belajar dari satu sama lain, atau tidak belajar apa-apa?"},
{n:72,type:"tf",micro:"Kerja sama bisa dilatih & membaik",q:"Benar atau Salah: Kemampuan sebuah tim bekerja sama tidak berubah dari proyek ke proyek; tim yang buruk di awal akan selalu buruk.",answer:false,explain:"Sebaliknya, tim juga 'berkembang': anggota belajar ritme, kekuatan, & cara komunikasi satu sama lain, jadi proyek ketiga sering lebih lancar dari yang pertama. Refleksi mempercepat ini.",hint:"Tim membaik dengan pengalaman, atau selalu sama?"},
{n:73,type:"mcq",micro:"Ketika tim benar-benar tidak berfungsi",q:"Kalau sebuah tim terus-menerus tidak berfungsi meski sudah dicoba diperbaiki, langkah yang wajar:",options:["Semua anggota menyerah diam-diam","Libatkan pihak luar (guru, pembimbing) untuk membantu menata ulang, atau pertimbangkan mengubah komposisi/pembagian","Terus memaksakan cara yang sama & berharap berubah"],answer:1,explain:"Ada titik di mana masalah bukan lagi soal usaha individu tapi struktur tim; bantuan luar atau perubahan struktur bisa perlu.",hint:"Bantuan luar / ubah struktur, atau paksa cara sama / menyerah?"},
{n:74,type:"mcq",micro:"Menilai 'kerja sama' vs 'menyalin'",q:"Beda kerja sama yang sah & mencontek dalam tugas individu:",options:["Keduanya sama","Kerja sama selalu berarti satu orang yang mengerjakan","Kerja sama: berbagi ide, berdiskusi, saling menjelaskan — tapi tiap orang menghasilkan karyanya sendiri bila tugasnya individu. Mencontek: menyalin jawaban orang"],answer:2,explain:"Untuk tugas kelompok, hasil bersama itu tujuannya. Untuk tugas individu, kolaborasi berhenti di berbagi pemahaman, bukan jawaban.",hint:"Berbagi pemahaman (individu) / hasil bersama (kelompok), atau menyalin jawaban?"},
{n:75,type:"tf",micro:"Menyuarakan masalah tim itu setia",q:"Benar atau Salah: Menyampaikan bahwa ada yang tidak beres dalam tim (dengan cara yang membangun) adalah bentuk kepedulian pada tim, bukan pengkhianatan.",answer:true,explain:"Diam sambil membiarkan tim menuju kegagalan bukan kesetiaan. Menyuarakan masalah agar bisa diperbaiki adalah tanggung jawab anggota.",hint:"Menyuarakan masalah = peduli, atau berkhianat?"},
{n:76,type:"mcq",micro:"Kerja sama lintas perbedaan",q:"Bekerja dalam tim yang anggotanya berbeda latar, kemampuan, & pendapat...",options:["Bisa lebih menantang tapi sering menghasilkan ide & solusi yang lebih kaya daripada tim yang semua mirip","Selalu lebih buruk daripada tim yang seragam","Tidak mungkin berhasil"],answer:0,explain:"Keberagaman sudut pandang menangkap titik buta yang tim seragam lewatkan — asalkan perbedaan dikelola dengan hormat.",hint:"Lebih menantang tapi lebih kaya, atau selalu lebih buruk?"},
{n:77,type:"mcq",micro:"Refleksi tim",q:"Setelah proyek, pertanyaan refleksi tim yang berguna:",options:["Tidak perlu refleksi, sudah selesai","Apa yang berjalan baik? Apa yang menghambat? Apa satu hal yang akan kita lakukan berbeda lain kali?","Siapa yang paling malas?"],answer:1,explain:"Refleksi yang fokus pada proses (bukan menyalahkan orang) mengubah tiap proyek jadi pelajaran untuk tim berikutnya.",hint:"Refleksi proses, atau mencari yang malas / tidak refleksi?"},
{n:78,type:"mcq",micro:"Peran anggota saat bukan ketua",q:"Kamu bukan ketua, tapi kamu tetap bisa memperkuat tim dengan...",options:["Menunggu semua arahan dari ketua & tidak berinisiatif","Diam-diam mengkritik ketua ke anggota lain","Menepati bagian, mengabari kendala, membantu yang tertinggal, mengajak yang diam bicara, & menjaga fokus rapat"],answer:2,explain:"Tim yang kuat tidak bergantung pada satu ketua; tiap anggota mengambil tanggung jawab kecil untuk kesehatan tim.",hint:"Ambil inisiatif memperkuat tim, atau tunggu arahan / kritik diam-diam?"},
{n:79,type:"mcq",micro:"Menilai tim dari luar",q:"Kalau kamu melihat tim lain: satu orang mengerjakan semua sambil kesal, sisanya main HP — kesimpulan yang tepat:",options:["Tim itu gagal berkolaborasi: kemungkinan tidak ada pembagian tugas, kesepakatan, atau cara menangani anggota pasif","Tim itu efisien karena ada yang produktif","Yang mengerjakan semua adalah pahlawan yang harus ditiru"],answer:0,explain:"Satu orang menanggung semua adalah GEJALA kegagalan tim, bukan model yang baik. Hasil mungkin jadi, tapi prosesnya tidak sehat & tidak adil.",hint:"Gejala kegagalan kolaborasi, atau model efisien?"},
{n:80,type:"open",micro:"Membandingkan dua tim",q:"Tim A: tidak ada pembagian tugas, semua menunggu ketua, konflik dipendam, satu orang akhirnya mengerjakan 80%. Tim B: pembagian tugas tertulis + tenggat, cek kemajuan tiap 3 hari, perbedaan pendapat dibahas terbuka, anggota saling bantu saat ada yang tertinggal. Keduanya menyelesaikan proyek. Jelaskan mengapa Tim B lebih sehat meski hasil akhirnya mungkin mirip (minimal 4 alasan), dan apa risiko cara Tim A dalam jangka panjang.",sample:"Tim B lebih sehat karena: (1) Beban terbagi adil, jadi tidak ada satu orang yang kelelahan dan tidak ada yang lepas tangan; semua ikut bertanggung jawab. (2) Semua anggota belajar dan berlatih keterampilan (mengerjakan bagian, berkoordinasi, menyelesaikan konflik), bukan hanya satu orang. (3) Hasil Tim B kemungkinan lebih kaya karena memakai ide dan pengecekan dari banyak orang, bukan satu sudut pandang. (4) Masalah di Tim B ketahuan lebih awal lewat cek kemajuan, jadi tidak ada kepanikan di akhir. (5) Hubungan antar anggota Tim B tetap baik karena konflik dibahas, bukan dipendam. Risiko cara Tim A dalam jangka panjang: orang yang mengerjakan 80% akan kelelahan, kesal, dan mungkin menolak bekerja sama dengan tim itu lagi; anggota lain tidak berkembang dan terbiasa menjadi penumpang gelap; kalau si 'pahlawan' sakit atau tidak ada di proyek berikutnya, tim runtuh karena tidak ada yang terbiasa bekerja; dan ketidakadilan yang dibiarkan merusak kepercayaan dan pertemanan. Hasil satu proyek mungkin mirip, tapi cara Tim A tidak berkelanjutan.",explain:"Jawaban baik memberi minimal 4 alasan Tim B lebih sehat (beban adil, semua belajar, hasil lebih kaya, masalah ketahuan dini, hubungan terjaga) dan menyebut risiko jangka panjang cara Tim A (kelelahan & kekesalan si pengerja, anggota lain tidak berkembang / jadi penumpang gelap, tim rapuh bila 'pahlawan' absen, kepercayaan rusak).",hint:"Bandingkan: keadilan beban, kesempatan belajar semua, kekayaan hasil, deteksi masalah, hubungan. Lalu risiko Tim A: kelelahan, tidak berkembang, rapuh, kepercayaan rusak."},

// FASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Kasus: tim dengan teman & bukan teman",q:"Timmu berisi sahabatmu & seseorang yang kurang kamu sukai. Sikap profesional:",options:["Menyabotase bagian orang yang tidak kamu sukai","Perlakukan semua anggota dengan hormat & adil berdasarkan kontribusi, bukan berdasarkan suka/tidak suka pribadi","Hanya bekerja sama dengan sahabat & mengabaikan yang lain"],answer:1,explain:"Kemampuan bekerja sama dengan orang yang tidak kamu sukai (secara sopan & profesional) adalah keterampilan berharga seumur hidup.",hint:"Hormat & adil ke semua, atau pilih-pilih / menyabotase?"},
{n:82,type:"mcq",micro:"Kasus: kamu ketua tim yang anggotanya lebih tua/senior",q:"Kamu ditunjuk mengoordinasi tim yang berisi kakak kelas. Sikap:",options:["Memerintah keras untuk membuktikan otoritasmu","Menyerahkan semua keputusan ke mereka & tidak mengoordinasi","Pimpin dengan melayani: fasilitasi kesepakatan, hormati pengalaman mereka, minta masukan, & tetap jaga kejelasan peran & tenggat"],answer:2,explain:"Kepemimpinan tim bukan soal usia tapi soal memfasilitasi. Menghormati + tetap menjaga struktur adalah kuncinya.",hint:"Memimpin dengan melayani + hormat, atau memerintah keras / menghilang?"},
{n:83,type:"tf",micro:"Refleksi: kerja sama = keterampilan masa depan",q:"Benar atau Salah: Kerja sama tim hanya relevan untuk tugas sekolah; di dunia kerja & kehidupan nyata, orang umumnya bekerja sendiri-sendiri.",answer:false,explain:"Sebaliknya, hampir semua pekerjaan & kegiatan penting melibatkan kerja sama. Kemampuan berkolaborasi menentukan seberapa jauh & seberapa nyaman kamu bisa berkontribusi.",hint:"Investasi jangka panjang, atau hanya untuk tugas sekolah?"},
{n:84,type:"mcq",micro:"Kasus: menyeimbangkan kualitas & kebersamaan",q:"Kamu bisa menghasilkan bagian yang lebih baik kalau mengerjakan sendiri, tapi tim ingin semua ikut. Sikap yang menyeimbangkan:",options:["Ajak tim mengerjakan bersama sambil kamu berbagi caramu; hasil sedikit di bawah 'versi solo'-mu tapi semua belajar & tim lebih kuat","Kerjakan sendiri & tolak bantuan siapa pun","Kerjakan sendiri diam-diam & pura-pura tim ikut"],answer:0,explain:"Kadang kolaborasi berarti menerima hasil yang sedikit kurang 'sempurna' demi keterlibatan & pembelajaran semua — trade-off yang sering sepadan.",hint:"Kerjakan bersama + bagikan caramu, atau solo diam-diam?"},
{n:85,type:"order",micro:"Memfasilitasi rapat tim yang efektif",q:"Urutkan langkah memimpin rapat tim 20 menit yang produktif.",items:["Sebutkan tujuan rapat & agenda di awal","Minta tiap orang melaporkan kemajuan & kendala secara singkat","Bahas & putuskan hal yang perlu diputuskan","Rangkum keputusan, tugas baru, & siapa mengerjakan apa sebelum bubar"],answer:[0,1,2,3],explain:"Tujuan & agenda → laporan singkat → keputusan → rangkuman siapa-apa-kapan. Rapat tanpa rangkuman sering tidak menghasilkan aksi.",hint:"Apa yang disampaikan di awal, & apa yang dirangkum di akhir?"},
{n:86,type:"mcq",micro:"Kasus: anggota membawa masalah pribadi berat",q:"Seorang anggota sedang menghadapi masalah keluarga berat & kontribusinya menurun. Sikap tim yang berempati & tetap fungsional:",options:["Keluarkan dia dari tim","Tunjukkan pengertian & dukungan, sesuaikan bebannya sementara bila memungkinkan, & tim menutupi kekurangan tanpa membuatnya merasa bersalah berlebihan","Tuntut dia berkontribusi sama seperti biasa"],answer:1,explain:"Tim yang manusiawi menyeimbangkan empati (mendukung anggota yang kesulitan) dengan tanggung jawab (menyelesaikan tugas), sering dengan penyesuaian sementara.",hint:"Empati + sesuaikan beban sementara, atau tuntut sama / keluarkan?"},
{n:87,type:"tf",micro:"Kerja sama tidak menghapus tanggung jawab individu",q:"Benar atau Salah: Meskipun hasil tim adalah tanggung jawab bersama, tiap anggota tetap punya tanggung jawab individu untuk menepati bagiannya & berkomunikasi.",answer:true,explain:"'Tanggung jawab bersama' bukan berarti 'tidak ada yang bertanggung jawab'. Justru tiap orang bertanggung jawab pada bagiannya DAN pada keseluruhan.",hint:"Bersama = tak ada yang bertanggung jawab, atau semua bertanggung jawab?"},
{n:88,type:"mcq",micro:"Kasus: keputusan tim ternyata keliru",q:"Tim mengambil keputusan bersama yang ternyata salah & merugikan hasil. Sikap yang matang:",options:["Menyalahkan siapa yang paling mendorong keputusan itu","Menyangkal bahwa keputusan itu salah","Refleksi bersama tanpa saling menyalahkan ('kita memutuskan ini dengan info yang kita punya saat itu; apa yang bisa kita pelajari & perbaiki sekarang?')"],answer:2,explain:"Keputusan bersama yang keliru adalah kesempatan belajar tim, bukan bahan tuduhan. Fokus pada perbaikan ke depan.",hint:"Refleksi tanpa menyalahkan, atau tuduh / menyangkal?"},
{n:89,type:"mcq",micro:"Kasus: kamu satu-satunya yang peduli",q:"Kamu merasa hanya kamu yang peduli pada kualitas hasil tim & itu melelahkan. Sikap yang sehat:",options:["Sampaikan perasaanmu ke tim dengan jujur, ajak mereka ikut memiliki standar, & bagi tanggung jawab pengecekan — jangan menanggung sendiri tanpa bilang","Terus menanggung semua sendiri sambil kesal","Menurunkan standarmu sampai sama seperti mereka & menyerah"],answer:0,explain:"Kepedulian yang dipendam jadi kelelahan & kekesalan. Menyuarakannya + membagi tanggung jawab lebih berkelanjutan.",hint:"Suarakan + bagi tanggung jawab, atau tanggung sendiri / menyerah?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu akan menjadi ketua panitia acara sekolah dengan 8 anggota yang belum saling kenal, waktu persiapan 3 minggu. Rancang bagaimana kamu akan membangun kerja sama tim yang solid dari nol — minimal 6 langkah konkret dengan alasan.",sample:"(1) Pertemuan pembuka: perkenalan singkat (nama, kelas, hal yang dikuasai/disukai), lalu sepakati bersama tujuan acara & seperti apa 'berhasil'. Alasan: orang bekerja lebih baik saat saling kenal & punya tujuan yang sama. (2) Bagi tim jadi 3-4 sub-tim kecil (mis. acara, konsumsi, publikasi, perlengkapan) dengan satu penanggung jawab tiap sub-tim. Alasan: kelompok kecil lebih mudah berkoordinasi daripada 8 orang sekaligus. (3) Buat pembagian tugas tertulis (siapa - apa - tenggat) di dokumen bersama, dan minta tiap orang konfirmasi. Alasan: menghindari 'kukira kamu yang urus'. (4) Sepakati cara & ritme komunikasi: grup chat utama + grup sub-tim, cek kemajuan singkat setiap 3 hari. Alasan: masalah ketahuan dini. (5) Tetapkan tenggat internal beberapa hari sebelum hari-H untuk semua persiapan selesai, menyisakan waktu untuk gladi & perbaikan. Alasan: mengurangi kepanikan menit terakhir. (6) Sepakati cara mengambil keputusan (dengar semua, lalu ketua/PJ memutuskan bila mepet) dan cara menyampaikan kendala (wajib kabari lebih awal, tidak menghilang). Alasan: kejelasan mencegah konflik. (7) Sebagai ketua, aku memimpin dengan melayani: memfasilitasi rapat, mengecek tiap PJ secara personal, mengapresiasi kontribusi secara terbuka, dan turun tangan membantu sub-tim yang tertinggal. Alasan: tim meniru sikap pemimpinnya. (8) Setelah acara, adakan refleksi singkat: apa yang berjalan baik, apa yang bisa lebih baik — dan rayakan bersama. Alasan: menutup dengan pembelajaran & kebersamaan.",explain:"Jawaban baik memuat minimal 6 langkah konkret dengan alasan: perkenalan + tujuan bersama, sub-tim kecil dengan PJ, pembagian tugas tertulis + konfirmasi, ritme komunikasi & cek kemajuan, tenggat internal sebelum hari-H, aturan keputusan & kendala, kepemimpinan melayani + apresiasi, refleksi & perayaan penutup.",hint:"Bangun dari nol: kenalan+tujuan, sub-tim, pembagian tertulis, komunikasi+cek, tenggat internal, aturan keputusan/kendala, pimpin dengan melayani, refleksi."},
{n:91,type:"mcq",micro:"Kasus: menyeimbangkan suara mayoritas & minoritas",q:"Dalam keputusan tim, mayoritas ingin A, tapi satu anggota punya kekhawatiran serius & spesifik soal A. Sikap tim yang bijak:",options:["Batalkan semua rencana karena satu orang tidak setuju","Dengarkan kekhawatirannya sungguh-sungguh, cek apakah bisa diatasi atau apakah ia melihat risiko nyata yang mayoritas lewatkan, baru putuskan","Abaikan karena kalah suara"],answer:1,explain:"Suara minoritas kadang menangkap risiko yang mayoritas lewatkan. Mendengarnya bukan berarti selalu menurutinya, tapi mempertimbangkannya serius.",hint:"Dengar & timbang kekhawatirannya, atau abaikan / batalkan semua?"},
{n:92,type:"tf",micro:"Refleksi: kerja sama butuh memberi & menerima",q:"Benar atau Salah: Kerja sama yang baik menuntut tiap anggota bersedia memberi (menepati bagian, membantu) DAN menerima (bantuan, umpan balik, keputusan bersama yang bukan pilihannya).",answer:true,explain:"Tim yang anggotanya hanya mau memberi tanpa menerima (atau sebaliknya) akan timpang. Keseimbangan memberi-menerima menjaga tim adil & solid.",hint:"Memberi & menerima keduanya, atau salah satu saja?"},
{n:93,type:"mcq",micro:"Kasus: tim virtual/online",q:"Timmu bekerja sama sepenuhnya online tanpa pernah bertemu. Yang menjadi lebih penting:",options:["Tidak ada yang berubah dari tim tatap muka","Menyerah karena online tidak mungkin","Komunikasi tertulis yang jelas, update rutin, dokumen bersama yang rapi, & tenggat yang tegas — karena tidak ada 'ketemu di kelas' untuk menyelaraskan"],answer:2,explain:"Tim online kehilangan koordinasi spontan, jadi struktur & komunikasi eksplisit harus menggantikannya.",hint:"Struktur & komunikasi eksplisit jadi lebih penting, atau tidak ada bedanya?"},
{n:94,type:"mcq",micro:"Kasus: menolak bergabung tim yang toksik",q:"Kamu diajak ke tim yang kamu tahu selama ini sering menjatuhkan anggotanya & tidak adil. Sikap:",options:["Kamu boleh menyampaikan kekhawatiranmu & menegosiasikan kesepakatan tim yang jelas sebagai syarat; atau, bila memungkinkan, memilih tidak bergabung — kesehatan tim itu penting","Wajib bergabung apa pun kondisinya","Bergabung lalu menjadi toksik juga"],answer:0,explain:"Kamu punya sedikit kendali atas tim mana yang kamu masuki, tapi kamu bisa menyuarakan syarat kerja sama yang sehat atau memilih keluar bila bisa.",hint:"Negosiasi kesepakatan sehat / pilih keluar bila bisa, atau wajib ikut / jadi toksik?"},
{n:95,type:"tf",micro:"Satu 'pahlawan' bukan tanda tim hebat",q:"Benar atau Salah: Tim yang punya satu anggota hebat yang selalu menyelamatkan proyek di menit terakhir adalah contoh tim yang kuat & patut ditiru.",answer:false,explain:"Sebaliknya, ketergantungan pada satu orang berarti tim runtuh bila ia absen, & anggota lain tidak berkembang. Tim hebat kuat karena banyak orang, bukan satu.",hint:"Ketergantungan satu pahlawan = hebat, atau rapuh?"},
{n:96,type:"mcq",micro:"Kasus: refleksi diri dalam tim",q:"Cara melatih keterampilan kerja samamu lewat refleksi:",options:["Tidak pernah mengevaluasi peranmu","Setelah tiap proyek tim, tanya diri: apakah aku menepati bagianku? apakah aku membantu yang lain? apakah aku mendengar & berkontribusi? apa satu hal yang akan kuperbaiki?","Menyimpulkan anggota lain yang salah setiap kali ada masalah"],answer:1,explain:"Menilai kontribusimu sendiri secara jujur (bukan hanya menilai orang lain) adalah cara tercepat menjadi anggota tim yang lebih baik.",hint:"Evaluasi peranmu sendiri, atau menyalahkan orang lain / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti kerja sama:",options:["Biarkan satu orang terpintar mengerjakan semua","Hindari semua konflik dengan diam","Sepakati tujuan bersama, bagi tugas secara adil sesuai kekuatan, komunikasikan kemajuan & kendala, saling bantu & percaya, selesaikan konflik dengan hormat, & ingat tim menang/kalah bersama — sambil tiap orang tetap bertanggung jawab pada bagiannya"],answer:2,explain:"Ringkasan: tujuan bersama + pembagian adil + komunikasi + saling bantu & percaya + konflik sehat + tanggung jawab bersama & individu.",hint:"Tujuan, pembagian adil, komunikasi, saling bantu, konflik sehat, tanggung jawab bersama — rangkai."},
{n:98,type:"tf",micro:"Refleksi: kerja sama melayani tujuan & orang",q:"Benar atau Salah: Kerja sama yang baik menghasilkan dua hal sekaligus: tugas selesai dengan baik, DAN anggota tim merasa dihargai serta belajar sesuatu.",answer:true,explain:"Kalau tugas selesai tapi semua orang kelelahan & saling kesal, kerja samanya belum berhasil sepenuhnya.",hint:"Tugas + orang, atau tugas saja?"},
{n:99,type:"mcq",micro:"Kasus: memulai jadi anggota tim yang lebih baik",q:"Cara termudah mulai memperbaiki kontribusimu di tim minggu ini:",options:["Pilih satu kebiasaan: menepati tenggat internal, atau mengirim update tanpa diminta, atau menawarkan bantuan ke satu anggota — dan lakukan konsisten","Menunggu sampai kamu jadi ketua","Berharap tim membaik dengan sendirinya"],answer:0,explain:"Perubahan tim sering dimulai dari satu anggota yang mengubah satu kebiasaan kecil secara konsisten.",hint:"Latih satu kebiasaan konsisten, atau menunggu jadi ketua / berharap?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi kerja sama",q:"Tulis 'aturan pribadi sebagai anggota tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",sample:"Contoh aturan pribadi: (1) Di awal kerja kelompok, aku ikut memastikan kami sepakati tujuan dan pembagian tugas tertulis dengan tenggat — karena tanpa itu kerja jadi kacau dan tidak adil. (2) Aku menepati bagianku tepat waktu, dan kalau ada kendala aku mengabari tim secepatnya, bukan menyembunyikannya sampai akhir — karena keterlambatanku memengaruhi semua orang. (3) Kalau bagianku selesai lebih dulu, aku menawarkan bantuan ke anggota yang tertinggal — karena tim menang atau kalah bersama. (4) Aku mendengarkan ide anggota lain dengan hormat dan mengajak yang pendiam bicara — karena tim terkuat memakai ide semua orang. (5) Kalau aku tidak setuju keputusan tim, aku menyampaikannya sekali dengan jelas, lalu mendukung keputusan bersama dan memberi yang terbaik — bukan menyabotase atau mengungkit terus. (6) Kalau ada anggota yang tidak berkontribusi, aku bicara langsung dengan sopan menanyakan kendalanya sebelum masalahnya membesar, dan tidak menggosipkannya. (7) Setelah proyek, aku menilai peranku sendiri secara jujur — apakah aku menepati, membantu, mendengar — dan memperbaiki satu hal lain kali.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: pastikan tujuan & pembagian tertulis di awal, menepati bagian + mengabari kendala dini, membantu yang tertinggal, mendengar & melibatkan yang pendiam, menyuarakan ketidaksetujuan sekali lalu mendukung keputusan, menangani anggota pasif lewat bicara langsung bukan gosip, refleksi peran sendiri.",hint:"Ambil satu pelajaran tiap fase — sepakati di awal, menepati+kabari, saling bantu, mendengar+melibatkan, dukung keputusan bersama, tangani pasif langsung, refleksi diri — jadikan aturan 'aku akan...'."},
];
